package redact

import (
	"encoding/json"
	"os"
	"testing"
)

// The cases' wanted output is what the old UriCleaner.remove_sensitive
// returned for them (testdata/uri_cases.json, generated by running the
// old redact.py), except where URIs deliberately does better (the tests
// after this one).
func TestURIsMatchesUriCleaner(t *testing.T) {
	b, err := os.ReadFile("testdata/uri_cases.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct{ In, Want string }
	if err := json.Unmarshal(b, &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		if got := URIs(c.In); got != c.Want {
			t.Errorf("URIs(%q)\n got %q\nwant %q", c.In, got, c.Want)
		}
	}
}

func TestURIsIn(t *testing.T) {
	v := map[string]any{"res": map[string]any{"invocation": map[string]any{"module_args": map[string]any{"repo": "https://u:p@h/x.git"}}, "list": []any{"https://a:b@c/"}}}
	got, _ := json.Marshal(URIsIn(v))
	want := `{"res":{"invocation":{"module_args":{"repo":"https://$encrypted$:$encrypted$@h/x.git"}},"list":["https://$encrypted$:$encrypted$@c/"]}}`
	if string(got) != want {
		t.Errorf("got %s", got)
	}
}

// Where the old code's substring replacement hit the wrong spot and left
// the password in place, the credentials are replaced where they stand.
func TestURIsReplacesInPlace(t *testing.T) {
	for in, want := range map[string]string{
		"https://u:p@h/x.git":            "https://$encrypted$:$encrypted$@h/x.git",
		"https://deploy:ttps@host/r.git": "https://$encrypted$:$encrypted$@host/r.git",
		"https://git:hub@github.com/x":   "https://$encrypted$:$encrypted$@github.com/x",
		"https://:only@h/":               "https://:$encrypted$@h/",
	} {
		if got := URIs(in); got != want {
			t.Errorf("URIs(%q) = %q, want %q", in, got, want)
		}
	}
}

// The old cleaner went on past each whole URI, so a URI nested in
// another's path, query or fragment kept its credentials.
func TestURIsNested(t *testing.T) {
	for in, want := range map[string]string{
		"https://host/path?next=ftp://u:p@inner/x more":                       "https://host/path?next=ftp://$encrypted$:$encrypted$@inner/x more",
		"https://a:b@host/r?u=https://c:d@inner/#f=ssh://e:f@x/":              "https://$encrypted$:$encrypted$@host/r?u=https://$encrypted$:$encrypted$@inner/#f=ssh://$encrypted$:$encrypted$@x/",
		"git clone https://host/redirect/https://user:tok@github.com/o/r.git": "git clone https://host/redirect/https://$encrypted$:$encrypted$@github.com/o/r.git",
		"https://host/plain/path?x=1 then http://u:p@h2/":                     "https://host/plain/path?x=1 then http://$encrypted$:$encrypted$@h2/",
		"https://host/a:b/c":                        "https://host/a:b/c",
		"file:///etc/x and https://h/?r=ftp://[bad": "file:///etc/x and https://h/?r=$encrypted$",
	} {
		if got := URIs(in); got != want {
			t.Errorf("URIs(%q)\n got %q\nwant %q", in, got, want)
		}
	}
}

// A URI right after a colour code or another word character still has its
// credentials removed.
func TestURIsAfterAdjacentText(t *testing.T) {
	for in, want := range map[string]string{
		"\x1b[0;31mhttps://user:s3cret@host/repo.git": "\x1b[0;31mhttps://$encrypted$:$encrypted$@host/repo.git",
		"_https://user:s3cret@host/x":                 "_https://$encrypted$:$encrypted$@host/x",
		"x 9https://user:s3cret@host/x":               "x 9https://$encrypted$:$encrypted$@host/x",
		"https://user:s3cret@host/x":                  "https://$encrypted$:$encrypted$@host/x",
	} {
		if got := URIs(in); got != want {
			t.Errorf("URIs(%q) = %q, want %q", in, got, want)
		}
	}
}
